{"command": "create", "path": "/root/output/js/visualization.js", "file_text": "// Stock market bubble chart + linked table.
// Data: /data/stock-descriptions.csv, one row per stock/ETF.

const WIDTH = 720;
const HEIGHT = 640;

const SECTOR_ORDER = [
    "Information Technology",
    "Financial",
    "Industry",
    "Energy",
    "ETF"
];

const SECTOR_COLORS = {
    "Information Technology": "#4C78A8",
    "Financial":              "#54A24B",
    "Industry":               "#F58518",
    "Energy":                 "#E45756",
    "ETF":                    "#9467BD"
};

// Cluster centers arranged in a compact layout, all near chart center so
// clusters stay close to each other rather than being flung to the corners.
const SECTOR_CENTERS = {
    "Information Technology": { x: WIDTH * 0.32, y: HEIGHT * 0.34 },
    "Financial":              { x: WIDTH * 0.68, y: HEIGHT * 0.34 },
    "Industry":               { x: WIDTH * 0.70, y: HEIGHT * 0.68 },
    "Energy":                 { x: WIDTH * 0.30, y: HEIGHT * 0.68 },
    "ETF":                    { x: WIDTH * 0.50, y: HEIGHT * 0.50 }
};

function formatMarketCap(v) {
    if (v == null || isNaN(v) || v === 0) return "—";
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
    if (v >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
    return d3.format(",")(v);
}

d3.csv("data/stock-descriptions.csv").then(raw => {
    const data = raw.map(d => ({
        ticker: d.ticker,
        sector: d.sector,
        fullName: d["full name"],
        marketCap: d.marketCap ? +d.marketCap : null,
        country: d.country || null,
        website: d.website || null
    }));

    // Deterministic ordering: by sector (in fixed order), then by descending market cap, then ticker.
    data.sort((a, b) => {
        const sa = SECTOR_ORDER.indexOf(a.sector);
        const sb = SECTOR_ORDER.indexOf(b.sector);
        if (sa !== sb) return sa - sb;
        const ma = a.marketCap ?? -1;
        const mb = b.marketCap ?? -1;
        if (mb !== ma) return mb - ma;
        return d3.ascending(a.ticker, b.ticker);
    });

    // Radius scale for stocks with market cap; fixed radius for ETFs.
    const stockCaps = data.filter(d => d.marketCap != null).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(stockCaps), d3.max(stockCaps)])
        .range([16, 54]);
    const ETF_RADIUS = 22;

    data.forEach(d => {
        d.r = d.marketCap != null ? radiusScale(d.marketCap) : ETF_RADIUS;
        const c = SECTOR_CENTERS[d.sector];
        // Deterministic initial positions at each cluster center prevent
        // simulation output from depending on default random placement.
        d.x = c.x;
        d.y = c.y;
    });

    renderBubbleChart(data);
    renderLegend();
    renderTable(data);
});

// ---- Bubble chart ----------------------------------------------------------

function renderBubbleChart(data) {
    const container = d3.select("#bubble-chart");
    const svg = container.append("svg")
        .attr("viewBox", `0 0 ${WIDTH} ${HEIGHT}`)
        .attr("preserveAspectRatio", "xMidYMid meet");

    const nodeG = svg.append("g").attr("class", "nodes");

    const groups = nodeG.selectAll("g.bubble-group")
        .data(data, d => d.ticker)
        .join("g")
        .attr("class", "bubble-group")
        .attr("data-ticker", d => d.ticker);

    groups.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.r)
        .attr("fill", d => SECTOR_COLORS[d.sector]);

    groups.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .style("font-size", d => Math.max(9, Math.min(14, d.r / 2.2)) + "px");

    const tooltip = d3.select("#tooltip");

    groups
        .on("mouseover", function(event, d) {
            // ETF entries have no marketCap/country/website — skip tooltip.
            if (d.sector === "ETF") return;
            tooltip
                .classed("visible", true)
                .html(
                    `<div class="tt-ticker">${d.ticker}</div>` +
                    `<div class="tt-name">${d.fullName}</div>` +
                    `<div class="tt-sector">Sector: ${d.sector}</div>`
                );
        })
        .on("mousemove", function(event, d) {
            if (d.sector === "ETF") return;
            tooltip
                .style("left", (event.pageX + 12) + "px")
                .style("top",  (event.pageY + 12) + "px");
        })
        .on("mouseout", function() {
            tooltip.classed("visible", false);
        })
        .on("click", function(event, d) {
            setSelection(d.ticker);
        });

    // Force simulation clustering by sector.
    const simulation = d3.forceSimulation(data)
        .force("x", d3.forceX(d => SECTOR_CENTERS[d.sector].x).strength(0.22))
        .force("y", d3.forceY(d => SECTOR_CENTERS[d.sector].y).strength(0.22))
        .force("collide", d3.forceCollide(d => d.r + 1.5).strength(1).iterations(3))
        .force("charge", d3.forceManyBody().strength(-6))
        .on("tick", () => {
            groups.attr("transform", d => {
                // Keep bubbles inside the SVG viewport.
                d.x = Math.max(d.r + 2, Math.min(WIDTH  - d.r - 2, d.x));
                d.y = Math.max(d.r + 2, Math.min(HEIGHT - d.r - 2, d.y));
                return `translate(${d.x}, ${d.y})`;
            });
        });

    // Run enough ticks to settle then stop — deterministic final layout.
    simulation.alpha(1).alphaDecay(0.03);
    for (let i = 0; i < 400; i++) simulation.tick();
    simulation.stop();
    groups.attr("transform", d => `translate(${d.x}, ${d.y})`);
}

// ---- Legend ----------------------------------------------------------------

function renderLegend() {
    const legend = d3.select("#legend");
    SECTOR_ORDER.forEach(sector => {
        const item = legend.append("div").attr("class", "legend-item");
        item.append("span")
            .attr("class", "legend-swatch")
            .style("background", SECTOR_COLORS[sector]);
        item.append("span").text(sector);
    });
}

// ---- Table -----------------------------------------------------------------

function renderTable(data) {
    const tbody = d3.select("#stock-table tbody");
    const rows = tbody.selectAll("tr")
        .data(data, d => d.ticker)
        .join("tr")
        .attr("data-ticker", d => d.ticker)
        .on("click", (event, d) => setSelection(d.ticker));

    rows.append("td").attr("class", "ticker").text(d => d.ticker);
    rows.append("td").text(d => d.fullName);
    rows.append("td").text(d => d.sector);
    rows.append("td").attr("class", "market-cap").text(d => formatMarketCap(d.marketCap));
}

// ---- Bidirectional selection ----------------------------------------------

let selectedTicker = null;

function setSelection(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;

    d3.selectAll("#stock-table tbody tr")
        .classed("selected", d => d && d.ticker === selectedTicker);

    d3.selectAll(".bubble-group circle")
        .classed("selected", d => d && d.ticker === selectedTicker);

    if (selectedTicker) {
        const row = document.querySelector(
            `#stock-table tbody tr[data-ticker="${selectedTicker}"]`
        );
        if (row) row.scrollIntoView({ block: "nearest", behavior: "smooth" });
    }
}
"}

{"command": "create", "path": "/tmp/smoke.js", "file_text": "// Headless smoke test: load index.html in jsdom, run scripts, verify DOM.
const { JSDOM, ResourceLoader } = require('jsdom');
const path = require('path');

class LocalLoader extends ResourceLoader {
    fetch(url, options) {
        if (url.startsWith('file://')) return super.fetch(url, options);
        // Rewrite http(s) requests to local files (shouldn't happen here)
        return super.fetch(url, options);
    }
}

const outDir = '/root/output';
const url = 'file://' + outDir + '/index.html';

JSDOM.fromFile(outDir + '/index.html', {
    url,
    runScripts: 'dangerously',
    resources: new LocalLoader(),
    pretendToBeVisual: true,
}).then(async dom => {
    // Wait for scripts + d3.csv promise to resolve
    await new Promise(r => setTimeout(r, 1500));
    const doc = dom.window.document;

    const rows = doc.querySelectorAll('#stock-table tbody tr');
    const bubbles = doc.querySelectorAll('.bubble-group');
    const legendItems = doc.querySelectorAll('.legend-item');
    console.log('table rows:', rows.length);
    console.log('bubbles:',    bubbles.length);
    console.log('legend items:', legendItems.length);

    // Sample first 3 table rows
    rows.forEach((r, i) => {
        if (i < 3 || i >= rows.length - 3) {
            const cells = [...r.querySelectorAll('td')].map(td => td.textContent);
            console.log('row', i, '->', cells.join(' | '));
        }
    });

    // Check bubble label + circle radius on a couple bubbles
    ['AAPL', 'SPY', 'HFC'].forEach(t => {
        const g = doc.querySelector(`.bubble-group[data-ticker="${t}"]`);
        if (!g) { console.log(t, 'MISSING'); return; }
        const c = g.querySelector('circle');
        const label = g.querySelector('text');
        const tf = g.getAttribute('transform');
        console.log(t, 'r=' + c.getAttribute('r'), 'fill=' + c.getAttribute('fill'), 'label=' + label.textContent, 'transform=' + tf);
    });

    // Try a click on a bubble and confirm row highlights
    const aaplGroup = doc.querySelector('.bubble-group[data-ticker="AAPL"]');
    aaplGroup.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true }));
    const selectedRow = doc.querySelector('#stock-table tbody tr.selected');
    const selectedCircle = doc.querySelector('.bubble-group[data-ticker="AAPL"] circle.selected');
    console.log('after clicking AAPL bubble -> selected row ticker:', selectedRow && selectedRow.getAttribute('data-ticker'));
    console.log('after clicking AAPL bubble -> circle has selected class:', !!selectedCircle);

    // Click a table row (MSFT) and confirm bubble highlights
    const msftRow = doc.querySelector('#stock-table tbody tr[data-ticker="MSFT"]');
    msftRow.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true }));
    const nowSelectedCircle = doc.querySelector('circle.selected');
    console.log('after clicking MSFT row -> selected circle ticker:',
        nowSelectedCircle && nowSelectedCircle.parentNode.getAttribute('data-ticker'));

    // Hover an ETF -> tooltip should NOT become visible; hover a stock -> tooltip visible
    const tooltip = doc.querySelector('#tooltip');
    const spyGroup = doc.querySelector('.bubble-group[data-ticker="SPY"]');
    spyGroup.dispatchEvent(new dom.window.MouseEvent('mouseover', { bubbles: true }));
    console.log('after hovering SPY (ETF) -> tooltip classes:', tooltip.className);

    const nvdaGroup = doc.querySelector('.bubble-group[data-ticker="NVDA"]');
    nvdaGroup.dispatchEvent(new dom.window.MouseEvent('mouseover', { bubbles: true }));
    console.log('after hovering NVDA -> tooltip classes:', tooltip.className);
    console.log('tooltip HTML:', tooltip.innerHTML.slice(0, 200));

    // Sanity: ensure no bubble is outside SVG bounds
    let outOfBounds = 0;
    doc.querySelectorAll('.bubble-group').forEach(g => {
        const tf = g.getAttribute('transform');
        const m = /translate\(([-\d.]+),\s*([-\d.]+)\)/.exec(tf);
        if (!m) return;
        const x = parseFloat(m[1]), y = parseFloat(m[2]);
        const r = parseFloat(g.querySelector('circle').getAttribute('r'));
        if (x - r < 0 || x + r > 720 || y - r < 0 || y + r > 640) outOfBounds++;
    });
    console.log('bubbles out of bounds:', outOfBounds);
}).catch(err => { console.error('ERR', err); process.exit(1); });
"}

